const source = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

function readPath(obj, path) {
  return path.split('.').reduce((acc, key) => {
    if (acc && typeof acc === 'object' && key in acc) return acc[key];
    return undefined;
  }, obj);
}

function pick(obj, paths, fallback = '') {
  for (const path of paths) {
    const value = readPath(obj, path);
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return fallback;
}

function pickBool(obj, paths, fallback = false) {
  for (const path of paths) {
    const value = readPath(obj, path);
    if (typeof value === 'boolean') return value;
    if (value === 1 || value === '1') return true;
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      if (['true', 'yes', 'sim', 'on'].includes(normalized)) return true;
      if (['false', 'no', 'nao', 'off'].includes(normalized)) return false;
    }
  }
  return fallback;
}

function normalizePhone(phone) {
  const digits = String(phone || '').replace(/\D+/g, '');
  if (!digits) return '';
  return digits.startsWith('55') ? digits : `55${digits}`;
}

const companyName = 'Sua Assistencia Tecnica';
const erpWebhookUrl = 'https://erp.seudominio.com/webhooks/whatsapp';
const erpWebhookToken = 'ALTERAR_TOKEN_WEBHOOK';
const gatewayUrl = 'http://127.0.0.1:3001';
const gatewayToken = 'ALTERAR_TOKEN_GATEWAY';
const erpOrigin = 'https://erp.seudominio.com';

const phone = normalizePhone(pick(source, [
  'from',
  'sender',
  'phone',
  'telefone',
  'number',
  'author',
  'chat_id',
  'jid',
  'data.from',
  'data.sender',
  'data.phone',
  'data.telefone',
  'data.number',
  'contact.phone',
  'contact.number',
  'data.contact.phone',
  'data.contact.number'
]));

const text = pick(source, [
  'message',
  'mensagem',
  'text',
  'body',
  'caption',
  'conteudo',
  'data.message',
  'data.mensagem',
  'data.text',
  'data.body',
  'data.caption',
  'data.conteudo'
], '');

const normalizedText = text
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

const hasMedia = pickBool(source, ['has_media', 'hasMedia', 'data.has_media', 'data.hasMedia'], false);
const fromMe = pickBool(source, ['from_me', 'fromMe', 'data.from_me', 'data.fromMe'], false);
const selfCheck = pickBool(source, ['self_check', 'data.self_check'], false);

let intent = 'fallback';
if (/\b(oi|ola|bom dia|boa tarde|boa noite|menu|inicio)\b/.test(normalizedText)) {
  intent = 'saudacao';
} else if (/\b(status|andamento|acompanhar|os|ordem)\b/.test(normalizedText)) {
  intent = 'status_os';
} else if (/\b(orcamento|orçamento|valor|preco|preço)\b/.test(normalizedText)) {
  intent = 'orcamento';
} else if (/\b(atendente|humano|pessoa|suporte|ajuda)\b/.test(normalizedText)) {
  intent = 'humano';
} else if (/\b(agendar|visita|coleta|retirada)\b/.test(normalizedText)) {
  intent = 'agendamento';
} else if (hasMedia && normalizedText === '') {
  intent = 'midia';
}

let replyMessage = '';
let shouldReply = !fromMe && !selfCheck && phone !== '';

if (shouldReply) {
  switch (intent) {
    case 'saudacao':
      replyMessage = `Olá. Você falou com a ${companyName}.\n\nDigite uma opção:\n1 - Consultar status da OS\n2 - Solicitar orçamento\n3 - Falar com um atendente`;
      break;
    case 'status_os':
      replyMessage = `Perfeito. Envie o número da sua OS para eu localizar o andamento do atendimento.`;
      break;
    case 'orcamento':
      replyMessage = `Certo. Envie o modelo do equipamento e o defeito informado para seguirmos com o orçamento.`;
      break;
    case 'humano':
      replyMessage = `Tudo bem. Vou encaminhar sua mensagem para um atendente humano e seguimos por aqui.`;
      break;
    case 'agendamento':
      replyMessage = `Recebido. Envie o melhor dia, turno e endereço para verificarmos a agenda.`;
      break;
    case 'midia':
      replyMessage = `Recebi seu anexo. Vou registrar o material e seguir com o atendimento.`;
      break;
    default:
      replyMessage = `Recebi sua mensagem. Em instantes seguimos o atendimento por aqui. Se preferir, envie o número da OS ou descreva o defeito do equipamento.`;
      break;
  }
}

const erpPayload = {
  ...(typeof source === 'object' ? source : { raw: String(source) }),
  n8n_workflow: 'atendimento-clientes-whatsapp',
  n8n_received_at: new Date().toISOString(),
  normalized_phone: phone,
  normalized_text: text,
  detected_intent: intent
};

return [{
  json: {
    ...$json,
    source,
    normalizedPhone: phone,
    receivedText: text,
    normalizedText,
    hasMedia,
    fromMe,
    selfCheck,
    intent,
    shouldReply,
    replyMessage,
    erpWebhookUrl,
    erpWebhookToken,
    gatewayUrl,
    gatewayToken,
    erpOrigin,
    erpPayload,
    gatewayPayload: {
      to: phone,
      number: phone,
      message: replyMessage
    }
  }
}];
